    public void testNullParentNode() {
        n = new Node(Token.NUMBER);
        checkSideEffects.visit(t, n, null);
        assertTrue(checkSideEffects.problemNodes.isEmpty());
    }

    @Test
    public void testExprResultNode() {
        n = new Node(Token.EXPR_RESULT);
        parent = new Node(Token.BLOCK);
        checkSideEffects.visit(t, n, parent);
        assertTrue(checkSideEffects.problemNodes.isEmpty());
    }

    @Test
    public void testBlockNode() {
        n = new Node(Token.BLOCK);
        parent = new Node(Token.SCRIPT);
        checkSideEffects.visit(t, n, parent);
        assertTrue(checkSideEffects.problemNodes.isEmpty());
    }

    @Test
    public void testQualifiedNameNodeWithJSDoc() {
        Node qualifiedName = new Node(Token.QUALIFIED_NAME);
        qualifiedName.setJSDocInfo(new JSDocInfoBuilder(false).build());
        checkSideEffects.visit(t, qualifiedName, null);
        assertTrue(checkSideEffects.problemNodes.isEmpty());
    }

