    public void testStringNode() {
        n = new Node(Token.STRING);
        parent = new Node(Token.SCRIPT);
        when(NodeUtil.isExpressionResultUsed(n)).thenReturn(false);
        checkSideEffects.visit(t, n, parent);
        assertFalse(checkSideEffects.problemNodes.isEmpty());
    }

    @Test
    public void testSimpleOpNode() {
        n = new Node(Token.ADD);
        parent = new Node(Token.SCRIPT);
        when(NodeUtil.isExpressionResultUsed(n)).thenReturn(false);
        when(NodeUtil.isSimpleOperatorType(n.getType())).thenReturn(true);
        checkSideEffects.visit(t, n, parent);
        assertFalse(checkSideEffects.problemNodes.isEmpty());
    }

    @Test
    public void testNodeWithSideEffects() {
        n = new Node(Token.CALL);
        parent = new Node(Token.SCRIPT);
        when(NodeUtil.isExpressionResultUsed(n)).thenReturn(false);
        when(NodeUtil.mayHaveSideEffects(n, t.getCompiler())).thenReturn(true);
        checkSideEffects.visit(t, n, parent);
        assertTrue(checkSideEffects.problemNodes.isEmpty());
    }

