                throw new Exception("Test Exception");
            }
        };
        compiler.runInCompilerThread(callable);
    }

    @Test
    public void testNewTracer(){
        Compiler compiler = new Compiler();
        Tracer tracer = compiler.newTracer("test");
        Assert.assertNotNull(tracer);
    }

    @Test
    public void testStopTracer(){
        Compiler compiler = new Compiler();
        Tracer tracer = compiler.newTracer("test");
        compiler.stopTracer(tracer, "test");
    }

