        visitor = new RestrictByOneTypeOfResultVisitor("function", false);
    }

    @Test
    public void testWhenValueIsFunction_And_ResultEqualsValueTrue_ReturnCtorType() {
        ObjectType type = ObjectType.fromFunction(registry.getFunctionType(registry.getType(U2U_CONSTRUCTOR_TYPE)), registry);
        Assert.assertEquals(registry.getType(U2U_CONSTRUCTOR_TYPE), visitor.caseObjectType(type));
    }

    @Test
    public void testWhenValueIsFunction_And_ResultEqualsValueTrue_CtorTypeOfSubtype() {
        JSType ctorType = registry.getType(U2U_CONSTRUCTOR_TYPE);
        ObjectType superType = ObjectType.getInstance(registry, "SuperType");
        superType = superType.copyAsSubtype(ctorType);
        Assert.assertEquals(ctorType, visitor.caseObjectType(superType));
    }

    @Test
    public void testWhenValueIsFunction_And_ResultEqualsValueFalse_ReturnNull() {
        ObjectType type = ObjectType.getInstance(registry, "Type");
        ObjectType ctorType = ObjectType.fromFunction(registry.getFunctionType(registry.getType(U2U_CONSTRUCTOR_TYPE)), registry);
        type = type.copyAsSubtype(ctorType);
        visitor = new RestrictByOneTypeOfResultVisitor("function", false);
        Assert.assertNull(visitor.caseObjectType(type));
    }

    @Test
    public void testWhenValueIsFunction_And_ResultEqualsValueFalse_ReturnType() {
        ObjectType type = ObjectType.getInstance(registry, "Type");
        visitor = new RestrictByOneTypeOfResultVisitor("function", false);
        Assert.assertEquals(type, visitor.caseObjectType(type));
    }

    @Test
    public void testWhenValueNotFunction_MatchesExpectation_ReturnType() {
